// План specs/addresses.md 3.1 (кейс AD-06). Admin, компания «test». Только просмотр.
import { test } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from './address-helpers';
import { TEST_CLIENT_ADDRESS, expectNoBrokenUnitFormat, expectUnitRightAfterStreet, pickAddress, textOf } from './address-display-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Адрес: Unit в списке клиентов (#b2f74544)', () => {
  test('Clients: Unit is shown right after the street, not after the country #b2f74544 @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);
    await page.goto('/customers');

    // Строки клиентов — по фрагменту id (имя «test» неоднозначно).
    const testRow = page.locator('tr', { hasText: '52bde720' }).first();
    const testText = await textOf(testRow, TEST_CLIENT_ADDRESS);
    expectUnitRightAfterStreet(pickAddress(testText, '2221 NW Federal Hwy'), 'Clients, «test»');

    // Тип квартиры («Apt 5B») показывается как есть, без «Unit Apt».
    const qaRow = page.locator('tr', { hasText: '50d37684' }).first();
    const qaText = await textOf(qaRow, /2221 Northwest Federal Highway, Apt [\w-]+, Stuart/);
    expectUnitRightAfterStreet(pickAddress(qaText, '2221 Northwest Federal Highway'), 'Clients, «QA-unit client»');

    expectNoBrokenUnitFormat(await page.locator('main').innerText(), 'Clients, вся таблица');
  });
});
